import{z as d,x as i,o as r,c as B,q as o,j as n,D as e,d as s,s as A,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"单周期数据通路","description":"","frontmatter":{"title":"单周期数据通路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/single-cycle-datapath.md","filePath":"cs/single-cycle-datapath.md","lastUpdated":1791063341000}'),p={name:"cs/single-cycle-datapath.md"};function m(c,a,D,C,h,P){const E=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="单周期数据通路" tabindex="-1">单周期数据通路 <a class="header-anchor" href="#单周期数据通路" aria-label="Permalink to &quot;单周期数据通路&quot;">​</a></h1><div class="epigraph"><p>一条指令在一个时钟周期内走完取指、译码、执行、访存、写回；周期长度等于最长那条路径。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/register-file">寄存器堆</a>提供了双读单写口。ALU、MUX、内存、PC 计数器此前都已有。本课不重做 6T 单元，也不从流水线五级另起。缺口是：<strong>把积木接成一台能跑 RV32I 子集的机器</strong>，并且规定一拍一条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>各块功能已知，还没有一张总图：PC 出地址取指令；指令字段进堆与立即数拼接；ALUSrc 在寄存器与立即数之间选；ALU 算；MemRead/MemWrite 访问数据存储器；MemtoReg 在 ALU 结果与读出数据之间选，写回堆；分支逻辑改 PC。缺口是这条组合路径外加 PC 与堆的边沿更新。</p><p>控制信号本课先当输入端口；下一课用真值表驱动它们。</p><h3 id="单周期不是「延迟槽里的单条」" tabindex="-1">单周期不是「延迟槽里的单条」 <a class="header-anchor" href="#单周期不是「延迟槽里的单条」" aria-label="Permalink to &quot;单周期不是「延迟槽里的单条」&quot;">​</a></h3><p>每条指令一个周期，周期必须盖住最慢指令（通常 <code>lw</code>：取指+堆+ALU+数据内存+写回 MUX+\\(t_{su}\\)）。<code>add</code> 也要等这个 \\(T\\)，浪费。这是故意的教学机，用来暴露关键路径；多周期与流水线是后课为修这个浪费。</p><p><span class="marginnote">Patterson/Hennessy 第 4 章先单周期再多周期再流水。指令存储器与数据存储器在图上分开（哈佛口），避免同拍取指又 <code>lw</code> 单口冲突。</span></p><p><span class="marginnote">数字实例：设取指 \\(2\\,\\mathrm{ns}\\)、堆读 \\(1\\,\\mathrm{ns}\\)、ALU \\(2\\,\\mathrm{ns}\\)、数据存储器 \\(2\\,\\mathrm{ns}\\)、写回 \\(1\\,\\mathrm{ns}\\)——<code>lw</code> 全程串过这些段，周期至少 \\(8\\,\\mathrm{ns}\\)；<code>add</code> 只用其中三段约 \\(6\\,\\mathrm{ns}\\)，但<strong>必须</strong>等满 \\(8\\,\\mathrm{ns}\\) 才能开下一拍。快的在陪慢的走。</span></p><p><span class="marginnote">初学者容易把「CPI=1」当快。CPI 只数每条指令占几拍；真实速度是 CPI \\(\\times\\) \\(T\\)。单周期 CPI=1 但 \\(T\\) 巨大，流水线 CPI 仍约 1 却把 \\(T\\) 砍到单段的长度——墙钟时间天差地别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 PC、指令存储器、堆、立即数扩展、ALU、数据存储器、若干 MUX、分支加法器。时序元件：PC、寄存器堆写、数据存储器写，同一时钟。组合其余。建立保持按<a href="/cs/setup-hold">前面的课</a>检查最长路径。</p>',13)),(r(),n(l,null,{default:e(()=>[A(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22PC%22%5D%20--%3E%20IM%5B%22%E5%8F%96%E6%8C%87%22%5D%0A%20%20IM%20--%3E%20RF%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20RF%20--%3E%20ALU%5B%22ALU%22%5D%0A%20%20ALU%20--%3E%20DM%5B%22%E6%95%B0%E6%8D%AE%E5%AD%98%E5%82%A8%E5%99%A8%22%5D%0A%20%20DM%20--%3E%20WB%5B%22%E5%86%99%E5%9B%9E%20MUX%22%5D%0A%20%20WB%20--%3E%20RF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"功能上 RV32I 的核心指令都能走完。性能上 CPI=1，但 \\(T\\) 很大，IPC 的墙钟时间差。后课流水线把同一张图切成多拍重叠；结构冒险来自本课已经分开的指令/数据口是否合并。",-1)),a[5]||(a[5]=t("p",null,"同一张图怎么同时服务四种指令？差别全在 MUX 的选择位上——每类指令在三个道岔上拨向不同方向：",-1)),(r(),n(l,null,{default:e(()=>[A(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22%E8%AF%91%E7%A0%81%E5%87%BA%E6%8E%A7%E5%88%B6%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20M1%7B%22RegDst%20%2F%20%E5%86%99%E5%93%AA%E4%B8%AA%20rd%3F%22%7D%0A%20%20DEC%20--%3E%20M2%7B%22ALUSrc%EF%BC%9A%E7%AC%AC%E4%BA%8C%E6%93%8D%E4%BD%9C%E6%95%B0%3F%22%7D%0A%20%20DEC%20--%3E%20M3%7B%22MemtoReg%EF%BC%9A%E5%86%99%E5%9B%9E%E5%93%AA%E8%B7%AF%3F%22%7D%0A%20%20LW%5B%22lw%EF%BC%9A%E8%AF%BB%E5%86%85%E5%AD%98%22%5D%20--%3E%20M2B%5B%22ALUSrc%3D1%EF%BC%9A%E7%94%A8%E7%AB%8B%E5%8D%B3%E6%95%B0%E5%81%8F%E7%A7%BB%22%5D%0A%20%20LW%20--%3E%20M3B%5B%22MemtoReg%3D1%EF%BC%9A%E9%80%89%E5%86%85%E5%AD%98%E8%AF%BB%E5%87%BA%22%5D%0A%20%20ADD%5B%22add%EF%BC%9AALU%20%E7%AE%97%22%5D%20--%3E%20M2A%5B%22ALUSrc%3D0%EF%BC%9A%E7%94%A8%20rs2%22%5D%0A%20%20ADD%20--%3E%20M3A%5B%22MemtoReg%3D0%EF%BC%9A%E9%80%89%20ALU%20%E7%BB%93%E6%9E%9C%22%5D%0A%20%20BR%5B%22beq%EF%BC%9A%E5%8F%AA%E5%88%A4%E4%B8%8D%E6%94%B9%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20SKIP%5B%22RegWrite%3D0%3Cbr%3E%E5%88%86%E6%94%AF%E9%80%BB%E8%BE%91%E6%94%B9%20PC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>可以把它想象成铁路道岔：轨道（数据通路）是铺死的，火车走哪条岔由控制信号扳。下一课的真值表就是这本「扳道岔时刻表」。</p><p><code>jal</code> 要把 PC+4 写进 <code>rd</code>，数据通路需一条回写 PC+4 的 MUX 输入，容易漏画。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现异常、不实现缓存。数据存储器仍是理想组合读、同步写的教学 SRAM。不把超标量双发射提前。</p><p>后课默认：单周期图上的控制线是下一课真值表的输出；硬件在一拍内完成一条指令。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单周期把取指到写回放进同一 \\(T\\)；\\(T\\) 由最慢指令定。</li><li>积木：PC、双存储器口、堆、ALU、MUX。</li><li>控制尚未生成；CPI=1 不是最快墙钟。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const M=d(p,[["render",m]]);export{F as __pageData,M as default};
